------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})

-- eDP-2 is the NVIDIA dGPU's mux copy of the internal panel (Advanced Optimus).
-- It can report "connected" on resume from sleep, and Hyprland then puts the
-- lock screen on it — a panel that can't actually display anything. Never enable it.
hl.monitor({
    output   = "eDP-2",
    disabled = true,
})


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "kitty"
local fileManager = "command -v nautilus >/dev/null && nautilus --new-window || dolphin"
local menu = "hyprlauncher"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function ()
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("env QT_QPA_PLATFORMTHEME=gtk3 qs -p ~/.config/quickshell/aeris-bar/shell.qml")
    hl.exec_cmd("~/.local/bin/dock-autohide")
    hl.exec_cmd("~/.local/bin/stay-awake on")   -- no sleep/suspend by default (coffee cup in the bar)
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("command -v vicinae >/dev/null && vicinae server")
    hl.exec_cmd("swayosd-server")
    -- Two terminals after login (both show the AerisOS greeting). The left one runs ÆRIS Agent and falls back to a
    -- shell when it exits; the right one starts a moment later so ÆRIS always takes the left side of the layout.
    -- These run Ghostty (needs -e before a command); Super+Q etc. still use `terminal`.
    hl.exec_cmd("ghostty -e bash -ic 'aeris; exec bash'")
    hl.exec_cmd("sleep 0.5 && ghostty")
end)


