local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal), { description = "Open terminal" })
hl.bind(mainMod .. " + G", hl.dsp.exec_cmd("ghostty"), { description = "Open ghostty (trial)" })
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close(), { description = "Close window" })
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"), { description = "Log out / exit Hyprland" })
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager), { description = "File manager" })
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }), { description = "Toggle floating window" })
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("cliphist list | wofi --dmenu | cliphist decode | wl-copy"), { description = "Clipboard history" })
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu), { description = "App launcher (hyprlauncher)" })
hl.bind("ALT + space", hl.dsp.exec_cmd("command -v vicinae >/dev/null && vicinae toggle || " .. menu), { description = "Search / launcher (Vicinae)" })   -- Spotlight-style search (Vicinae, falls back to hyprlauncher)
hl.bind(mainMod .. " + K", hl.dsp.exec_cmd("~/.local/bin/keybinds"), { description = "Keyboard shortcuts cheat sheet" })
-- Web apps (Omarchy-style): open the site in its own frameless Brave window
local function webapp(url) return hl.dsp.exec_cmd("brave --app=" .. url) end
hl.bind(mainMod .. " + SHIFT + C", webapp("https://calendar.notion.so"), { description = "Notion Calendar" })
hl.bind(mainMod .. " + SHIFT + Y", webapp("https://youtube.com"), { description = "YouTube" })
hl.bind(mainMod .. " + SHIFT + I", webapp("https://claude.ai"), { description = "Claude" })
hl.bind(mainMod .. " + SHIFT + G", webapp("https://gemini.google.com"), { description = "Gemini" })
hl.bind(mainMod .. " + SHIFT + slash", webapp("https://www.google.com"), { description = "Google" })
-- Apps (Omarchy-style SUPER+SHIFT+letter)
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd("brave"), { description = "Browser (Brave)" })
hl.bind(mainMod .. " + SHIFT + N", hl.dsp.exec_cmd("subl"), { description = "Editor (Sublime Text)" })
hl.bind(mainMod .. " + SHIFT + O", hl.dsp.exec_cmd("obsidian"), { description = "Notes (Obsidian)" })
hl.bind(mainMod .. " + SHIFT + M", hl.dsp.exec_cmd("signal-desktop"), { description = "Messages (Signal)" })
-- AerisOS system menu: power, toggles, capture, settings, battery, update
hl.bind(mainMod .. " + ALT + space", hl.dsp.exec_cmd("~/.local/bin/aeris-menu"), { description = "AerisOS menu" })
-- Bar and quick panels (Omarchy-style)
hl.bind(mainMod .. " + SHIFT + space", hl.dsp.exec_cmd("qs ipc -p ~/.config/quickshell/aeris-bar/shell.qml call bar toggle"), { description = "Hide / show top bar" })
hl.bind(mainMod .. " + CTRL + A", hl.dsp.exec_cmd("kitty --class tui-float wiremix"), { description = "Audio settings" })
hl.bind(mainMod .. " + CTRL + W", hl.dsp.exec_cmd("kitty --class tui-float nmtui"), { description = "Wi-Fi / network settings" })
hl.bind(mainMod .. " + CTRL + B", hl.dsp.exec_cmd("kitty --class tui-float bluetui"), { description = "Bluetooth" })
hl.bind(mainMod .. " + CTRL + N", hl.dsp.exec_cmd("~/.local/bin/dnd toggle"), { description = "Do Not Disturb on / off" })
hl.bind(mainMod .. " + CTRL + I", hl.dsp.exec_cmd("~/.local/bin/stay-awake toggle"), { description = "Stay Awake on / off" })
